def move_site_dns_to_bases(apps, schema_editor):
    """Per-site DNS servers and domains (0024) become the DNS bases "dns" and "domain", and
    preference lists are rewritten from site / site:<name> / other-sites to the base syntax."""
    import re

    Firewall = apps.get_model("fleet", "Firewall")
    DnsBase = apps.get_model("fleet", "DnsBase")
    DnsBaseValue = apps.get_model("fleet", "DnsBaseValue")
    DnsPreference = apps.get_model("fleet", "DnsPreference")
    firewalls = list(Firewall.objects.all())
    for field, base_name, kind in (("site_dns_servers", "dns", "servers"), ("site_domain", "domain", "domains")):
        valued = [fw for fw in firewalls if (getattr(fw, field) or "").strip()]
        if not valued:
            continue
        base, _ = DnsBase.objects.get_or_create(
            name=base_name, defaults={"kind": kind, "description": "Moved from each firewall's site DNS settings."}
        )
        for fw in valued:
            DnsBaseValue.objects.update_or_create(base=base, firewall=fw, defaults={"value": getattr(fw, field).strip()})

    def rewrite(text, base_name):
        tokens = [t.strip() for t in re.split(r"[,\s]+", text or "") if t.strip()]
        result = []
        for token in tokens:
            lower = token.lower()
            if lower == "site":
                result.append(f"this.{base_name}")
            elif lower == "other-sites":
                result.append(f"others.{base_name}")
            elif lower.startswith("site:"):
                result.append(f"{token[5:]}.{base_name}")
            else:
                result.append(token)
        return ", ".join(result)

    for preference in DnsPreference.objects.all():
        preference.dns_servers = rewrite(preference.dns_servers, "dns")
        preference.search_domains = rewrite(preference.search_domains, "domain")
        preference.save(update_fields=["dns_servers", "search_domains"])


